// Parser de pedidos HTTP/1.1 sobre texto, sin red. Devuelve qué hacer con lo recibido hasta ahora.
function parsear(recibido) {
  const fin = recibido.indexOf('\r\n\r\n');
  if (fin === -1) return { estado: 'faltan bytes (no llegó la línea vacía)' };

  const [primera, ...resto] = recibido.slice(0, fin).split('\r\n');
  const partes = primera.split(' ');
  if (partes.length !== 3 || !partes[2].startsWith('HTTP/1.')) {
    return { estado: '400 Bad Request: línea de pedido inválida', linea: primera };
  }
  const campos = {};
  for (const linea of resto) {
    const i = linea.indexOf(':');
    campos[linea.slice(0, i).trim().toLowerCase()] = linea.slice(i + 1).trim();
  }
  const largo = Number(campos['content-length'] ?? 0);
  const cuerpo = recibido.slice(fin + 4);
  const bytesCuerpo = new TextEncoder().encode(cuerpo).length;
  if (bytesCuerpo < largo) return { estado: `faltan bytes del cuerpo (${bytesCuerpo} de ${largo})` };

  return { estado: 'pedido completo', metodo: partes[0], destino: partes[1], campos, cuerpo, sobra: bytesCuerpo - largo };
}

