const net = require('node:net');

const PUERTO = Number(process.env.PUERTO || 19073);
const MAX_CABECERA = 8 * 1024;   // bytes de línea de pedido + encabezados
const MAX_CUERPO = 1024 * 1024;  // 1 MiB

// datos inventados
const pedidos = new Map([
  [42, { id: 42, cliente: 'Ferreteria Norte', bultos: 12, estado: 'en ruta' }],
  [43, { id: 43, cliente: 'Libreria Sur', bultos: 3, estado: 'preparando' }],
]);
let proximoId = 44;

// ---------- parsing de solicitud ----------
function error(codigo, frase, motivo) {
  return { error: { codigo, frase, motivo } };
}

// Devuelve null si todavía faltan bytes, {error} si el pedido es inválido,
// o {pedido, consumidos} cuando hay un pedido completo al principio de buf.
function leerPedido(buf) {
  const fin = buf.indexOf('\r\n\r\n');
  if (fin === -1) {
    return buf.length > MAX_CABECERA ? error(431, 'Request Header Fields Too Large', 'encabezados demasiado largos') : null;
  }
  if (fin > MAX_CABECERA) return error(431, 'Request Header Fields Too Large', 'encabezados demasiado largos');

  const lineas = buf.subarray(0, fin).toString('latin1').split('\r\n');
  const partes = lineas[0].split(' ');
  if (partes.length !== 3 || !/^HTTP\/1\.[01]$/.test(partes[2])) {
    return error(400, 'Bad Request', 'línea de pedido inválida');
  }
  const [metodo, destino, version] = partes;

  const campos = {};
  for (const linea of lineas.slice(1)) {
    const i = linea.indexOf(':');
    if (i <= 0) return error(400, 'Bad Request', 'línea de encabezado inválida');
    campos[linea.slice(0, i).trim().toLowerCase()] = linea.slice(i + 1).trim();
  }
  if (version === 'HTTP/1.1' && !campos.host) return error(400, 'Bad Request', 'falta Host');
  if (campos['transfer-encoding']) return error(501, 'Not Implemented', 'no entiendo Transfer-Encoding');

  let largo = 0;
  if (campos['content-length'] !== undefined) {
    if (!/^\d+$/.test(campos['content-length'])) return error(400, 'Bad Request', 'Content-Length inválido');
    largo = Number(campos['content-length']);
    if (largo > MAX_CUERPO) return error(413, 'Content Too Large', 'cuerpo demasiado grande');
  }
  const desde = fin + 4;
  if (buf.length < desde + largo) return null;   // el cuerpo no terminó de llegar

  const cuerpo = buf.subarray(desde, desde + largo);
  return { pedido: { metodo, destino, version, campos, cuerpo }, consumidos: desde + largo };
}

// ---------- lógica: qué contestar ----------
function atender({ metodo, destino, cuerpo }) {
  const ruta = destino.split('?')[0];
  const coincide = ruta.match(/^\/pedidos\/(\d+)$/);

  if (ruta === '/pedidos') {
    if (metodo === 'GET' || metodo === 'HEAD') return { codigo: 200, frase: 'OK', json: [...pedidos.values()] };
    if (metodo === 'POST') {
      let datos;
      try { datos = JSON.parse(cuerpo.toString('utf8')); } catch { datos = null; }
      if (!datos || typeof datos.cliente !== 'string') {
        return { codigo: 400, frase: 'Bad Request', json: { error: 'el cuerpo no es un JSON con «cliente»' } };
      }
      const nuevo = { id: proximoId++, cliente: datos.cliente, bultos: datos.bultos ?? 1, estado: 'preparando' };
      pedidos.set(nuevo.id, nuevo);
      return { codigo: 201, frase: 'Created', json: nuevo, extra: { Location: `/pedidos/${nuevo.id}` } };
    }
    return { codigo: 405, frase: 'Method Not Allowed', json: { error: 'método no permitido' }, extra: { Allow: 'GET, HEAD, POST' } };
  }
  if (coincide) {
    if (metodo !== 'GET' && metodo !== 'HEAD') {
      return { codigo: 405, frase: 'Method Not Allowed', json: { error: 'método no permitido' }, extra: { Allow: 'GET, HEAD' } };
    }
    const p = pedidos.get(Number(coincide[1]));
    return p ? { codigo: 200, frase: 'OK', json: p } : { codigo: 404, frase: 'Not Found', json: { error: 'no existe ese pedido' } };
  }
  return { codigo: 404, frase: 'Not Found', json: { error: 'no existe esa ruta' } };
}

// ---------- armar la respuesta ----------
function armar(r, { sinCuerpo = false, cerrar = false } = {}) {
  const datos = Buffer.from(JSON.stringify(r.json) ?? '', 'utf8');
  const campos = {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': datos.length,
    ...(cerrar ? { Connection: 'close' } : {}),
    ...r.extra,
  };
  let cabecera = `HTTP/1.1 ${r.codigo} ${r.frase}\r\n`;
  for (const [k, v] of Object.entries(campos)) cabecera += `${k}: ${v}\r\n`;
  return Buffer.concat([Buffer.from(cabecera + '\r\n', 'latin1'), sinCuerpo ? Buffer.alloc(0) : datos]);
}

// ---------- la conexión ----------
const servidor = net.createServer((socket) => {
  let buf = Buffer.alloc(0);
  let n = 0;
  console.log(`[${socket.remotePort}] conexión nueva`);
  socket.setTimeout(5000, () => { console.log(`[${socket.remotePort}] inactiva: la cierro`); socket.destroy(); });

  socket.on('data', (trozo) => {
    buf = Buffer.concat([buf, trozo]);
    while (true) {                       // puede haber más de un pedido en el buffer
      const leido = leerPedido(buf);
      if (leido === null) return;        // faltan bytes: esperamos el próximo 'data'
      if (leido.error) {
        const e = leido.error;
        console.log(`[${socket.remotePort}] pedido inválido: ${e.motivo} -> ${e.codigo}`);
        socket.end(armar({ codigo: e.codigo, frase: e.frase, json: { error: e.motivo } }, { cerrar: true }));
        return;
      }
      buf = buf.subarray(leido.consumidos);
      const { pedido } = leido;
      n++;
      const cierra = pedido.campos.connection?.toLowerCase() === 'close' || pedido.version === 'HTTP/1.0';
      const r = atender(pedido);
      console.log(`[${socket.remotePort}] #${n} ${pedido.metodo} ${pedido.destino} -> ${r.codigo}`);
      socket.write(armar(r, { sinCuerpo: pedido.metodo === 'HEAD', cerrar: cierra }));
      if (cierra) return socket.end();
    }
  });
  socket.on('error', (e) => console.log(`[${socket.remotePort}] error de socket: ${e.code}`));
  socket.on('close', () => console.log(`[${socket.remotePort}] conexión cerrada tras ${n} pedido(s)`));
});

servidor.listen(PUERTO, '127.0.0.1', () => console.log(`escuchando en 127.0.0.1:${PUERTO}`));

